"""Convert between integers 1..3999 and canonical upper-case Roman numerals."""
import re

_VALUES = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]
_SYMBOLS = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

# Each group is the canonical form of one decimal place (thousands, hundreds, tens, units).
_CANONICAL = re.compile(
    r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})"
)


def to_roman(n):
    """Return the standard upper-case numeral for n, which must be an int from 1 to 3999."""
    if isinstance(n, bool) or not isinstance(n, int) or not 1 <= n <= 3999:
        raise ValueError(f"expected an integer from 1 to 3999, got {n!r}")
    parts = []
    for value, symbol in _VALUES:
        count, n = divmod(n, value)
        parts.append(symbol * count)
    return "".join(parts)


def from_roman(s):
    """Return the integer for a canonical upper-case numeral such as "MCMXCIV"."""
    if not isinstance(s, str) or not s or not _CANONICAL.fullmatch(s):
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    total = 0
    for i, ch in enumerate(s):
        value = _SYMBOLS[ch]
        nxt = _SYMBOLS[s[i + 1]] if i + 1 < len(s) else 0
        total += -value if value < nxt else value
    return total

