import contextlib
import io
import unittest

from textkit.cli import main
from textkit.roman import from_roman, to_roman


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class ToRomanTest(unittest.TestCase):
    def test_known_values(self):
        cases = {1: "I", 4: "IV", 9: "IX", 14: "XIV", 40: "XL", 90: "XC",
                 400: "CD", 944: "CMXLIV", 1994: "MCMXCIV", 3999: "MMMCMXCIX"}
        for n, numeral in cases.items():
            with self.subTest(n=n):
                self.assertEqual(to_roman(n), numeral)

    def test_rejects_out_of_range(self):
        for n in (0, 4000, -1):
            with self.subTest(n=n):
                with self.assertRaises(ValueError):
                    to_roman(n)

    def test_rejects_non_integers(self):
        for n in (True, 1.5, "5"):
            with self.subTest(n=n):
                with self.assertRaises(ValueError):
                    to_roman(n)


class FromRomanTest(unittest.TestCase):
    def test_known_values(self):
        self.assertEqual(from_roman("MCMXCIV"), 1994)
        self.assertEqual(from_roman("MMMCMXCIX"), 3999)

    def test_rejects_non_canonical(self):
        for s in ("IIII", "IC", "VX", "mcm", "", "IIV", "VV", "MMMM", "XM", "ABC", "I I"):
            with self.subTest(s=s):
                with self.assertRaises(ValueError):
                    from_roman(s)

    def test_round_trips_every_value(self):
        for n in range(1, 4000):
            with self.subTest(n=n):
                self.assertEqual(from_roman(to_roman(n)), n)


class RomanCommandTest(unittest.TestCase):
    def test_digits_print_numeral(self):
        self.assertEqual(run("roman", "1994"), (0, "MCMXCIV\n", ""))

    def test_numeral_prints_integer(self):
        self.assertEqual(run("roman", "MCMXCIV"), (0, "1994\n", ""))

    def test_non_canonical_exits_2_with_error(self):
        code, out, err = run("roman", "IIII")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_out_of_range_digits_exit_2(self):
        code, _, err = run("roman", "4000")
        self.assertEqual(code, 2)
        self.assertTrue(err.startswith("error: "))

    def test_json_wraps_output(self):
        code, out, _ = run("--json", "roman", "4")
        self.assertEqual(code, 0)
        self.assertIn('"output": ["IV"]', out)


if __name__ == "__main__":
    unittest.main()

